INSERT INTO client_department_obligations (client_id, department_id, obligation_id)
SELECT c.id, 'af36437e-da3d-4c6e-bd71-e6584fa96843', '6258db4a-dc3c-49d4-913d-0f26d53ece9e'
FROM clients c
WHERE c.sci_code IN ('8','10','16','18','20','29','32','43','44','45','46','48','50','55','58','66','70','72','76','78','88','94','110','111','123','127','136','145','153','157','162','168','169','170','176','178','185','190','194','195','204','210','213','214','216','224','246','254','255','63','67','75','95','121','125','171','172','175','196','201','207','235','240','242','109','5','22','64','132','24','51','187')
AND NOT EXISTS (
  SELECT 1 FROM client_department_obligations cdo
  WHERE cdo.client_id = c.id AND cdo.obligation_id = '6258db4a-dc3c-49d4-913d-0f26d53ece9e' AND cdo.department_id = 'af36437e-da3d-4c6e-bd71-e6584fa96843'
);
INSERT INTO obligation_instances (client_id, obligation_id, reference_month, status)
SELECT c.id, '6258db4a-dc3c-49d4-913d-0f26d53ece9e', m.month, 'pending'
FROM clients c
CROSS JOIN (VALUES ('2026-03-01'::date),('2026-04-01'::date),('2026-05-01'::date),('2026-06-01'::date),('2026-07-01'::date),('2026-08-01'::date),('2026-09-01'::date),('2026-10-01'::date),('2026-11-01'::date),('2026-12-01'::date)) AS m(month)
WHERE c.sci_code IN ('8','10','16','18','20','29','32','43','44','45','46','48','50','55','58','66','70','72','76','78','88','94','110','111','123','127','136','145','153','157','162','168','169','170','176','178','185','190','194','195','204','210','213','214','216','224','246','254','255','63','67','75','95','121','125','171','172','175','196','201','207','235','240','242','109','5','22','64','132','24','51','187')
AND NOT EXISTS (
  SELECT 1 FROM obligation_instances oi
  WHERE oi.client_id = c.id AND oi.obligation_id = '6258db4a-dc3c-49d4-913d-0f26d53ece9e' AND oi.reference_month = m.month
);